/** Pinned selected R3 payload closure; adapter has no remote or generated asset fallback. */
export async function loadSelectedAssets({contract:c,rootURL,bytes,image,rgba,makeCanvas,sha}){
 const base=new URL(c.environment.consumerBase,rootURL),json=async(path,pin)=>JSON.parse(new TextDecoder().decode(await bytes(new URL(path,base),pin))),typed=async(path,pin,T)=>new T(await bytes(new URL(path,base),pin));
 const M=await json('MANIFEST.json',c.environment.manifest.sha256),contract=await json(M.derivedContract,M.derivedContractSHA);if(M.sourceSHA!==c.environment.selectedSourceSHA||M.sourceSHA!==c.sources.exterior.sha256)throw Error('SOURCE_AUTHORITY_MISMATCH');
 const source=await image(new URL(M.source,base),M.sourceSHA),indices=await typed(M.water.indices,M.water.indicesSHA,Uint32Array),rgb=await typed(M.water.rgb,M.water.rgbSHA,Uint8Array),actors=await Promise.all(Array.from({length:12},(_,i)=>image(new URL(`actor${i}.png`,base),M.actors[`actor${i}.png`]))),actorData=actors.map(rgba),safeImage=await image(new URL(M.safePNG,base),M.safeSHA),safeData=rgba(safeImage);
 let raw=rgba(source),region=new Uint8Array(indices.length*4);indices.forEach((id,i)=>region.set(raw.subarray(id*4,id*4+4),i*4));if(await sha(region)!==contract.water.newRegionSHA)throw Error('WATER_REGION_CHANGED');for(const s of contract.signs){const[x0,y0,x1,y1]=s.rect,a=new Uint8Array((x1-x0)*(y1-y0)*4);let p=0;for(let y=y0;y<y1;y++){a.set(raw.subarray((y*5120+x0)*4,(y*5120+x1)*4),p);p+=(x1-x0)*4}if(await sha(a)!==s.originalAndDerivedRGBARegionSHA)throw Error('SIGN_REGION_CHANGED')}
 const signs=await Promise.all(M.signs.map(async s=>({...s,image:await image(new URL(s.png,base),s.sha)}))),depthAssets=await Promise.all(M.depth.map(async d=>({...d,pixels:rgba(await image(new URL(d.png,base),d.sha))}))),b2Contract=await json(M.b2.contract,M.b2.sha),b2Atlas=await image(new URL(b2Contract.atlas,base),b2Contract.atlasSHA),b3Contract=await json(M.b3.contract,M.b3.contractSHA),b3Atlas=await image(new URL(M.b3.atlas,base),M.b3.atlasSHA);
 if(b2Atlas.width!==8192||b2Atlas.height!==1920||b3Atlas.width!==6560||b3Atlas.height!==1560||b3Contract.atlasSHA!==M.b3.atlasSHA)throw Error('BOAT_ATLAS_PROOF');
 const payload=async b=>({indices:await typed(b.indices,b.indicesSHA,Uint32Array),rgb:await typed(b.rgb,b.rgbSHA,Uint8Array),sourceSHA:b.sourceSHA,revision:b.revision}),b1Payload=await payload(M.b1),b4Payload=await payload(M.b4),LM=await json('lighting-MANIFEST.json',c.environment.lightingManifest.sha256),lightIds=await typed('lighting-indices.u32',LM.indicesSHA,Uint32Array),lightTransmission=await typed('lighting-transmission.f64',LM.transmissionSHA,Float64Array),rc=makeCanvas(107,107);
 return {M,contract,source,indices,rgb,actors,actorData,zeroActorData:actors.map(()=>new Uint8ClampedArray(107*107*4)),safeData,signs,depthAssets,b2Contract,b2Atlas,b3Contract,b3Atlas,b1Payload,b4Payload,LM,lightIds,lightTransmission,rc,rz:rc.getContext('2d'),lightingFrame:new Uint8ClampedArray(960*540*4),actorMask:new Uint8Array(960*540)};
}
